@startuml

class EBike {
  + modelNumber : string
  + weight : float
}

class Frame {
  + material : string
}

class DriveSystem {
  + maxTorque : float
}

class Motor {
  + powerOutput : float
}

class Controller {
  + currentState : ControllerState
}

class BasicController {}

class AdvancedController {
  + nextMaintenanceDate : date
}

class Battery {
  + energyCapacityWh : float
}

class Wheel {}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "1" *-- "0..1" Battery
EBike "1" *-- "2" Wheel
DriveSystem "1" *-- "1" Motor
BasicController --|> Controller
AdvancedController --|> Controller
Controller --> Battery : controls
Controller --> DriveSystem : commands

@enduml

